function Emblem({ size = 44 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 100 100">
      <circle cx="50" cy="50" r="48" fill="none" stroke="#D9C68A" strokeWidth="2" />
      <circle cx="50" cy="50" r="40" fill="none" stroke="#D9C68A" strokeWidth="1" />
      {Array.from({ length: 24 }).map((_, i) => {
        const a = (i / 24) * Math.PI * 2;
        return <line key={i} x1={50 + 40*Math.cos(a)} y1={50 + 40*Math.sin(a)} x2={50 + 46*Math.cos(a)} y2={50 + 46*Math.sin(a)} stroke="#D9C68A" strokeWidth="1.4" />;
      })}
      <circle cx="50" cy="50" r="6" fill="#D9C68A" />
      <path d="M50 20 L54 44 L50 50 L46 44 Z" fill="#D9C68A" opacity="0.9" />
    </svg>
  );
}

function RiskBadge({ level }) {
  return (
    <span style={{
      background: riskColor(level), color: "#fff",
      border: `1px solid ${riskColor(level)}`, borderRadius: 3,
      padding: "3px 10px", fontSize: 12.5, fontWeight: 700, letterSpacing: 0.2,
      display: "inline-block", whiteSpace: "nowrap",
    }}>{level}</span>
  );
}

function TrendPill({ v }) {
  const up = v > 0, flat = v === 0;
  const color = flat ? C.inkSoft : up ? C.redBright : C.greenGood;
  const Icon = flat ? Minus : up ? ArrowUp : ArrowDown;
  return (
    <span style={{ color, display: "inline-flex", alignItems: "center", gap: 3, fontWeight: 700, fontSize: 13.5 }}>
      <Icon size={14} strokeWidth={2.6} />{Math.abs(v)}%
    </span>
  );
}

